      hu: ["Magas fokú automatizálás", "Kiváló minőségű szenet termel", "A Shenhua Group üzemelteti"],
      ro: ["Grad ridicat de automatizare", "Produce cărbune de înaltă calitate", "Operată de Shenhua Group"],
